class Solution:
    def licenseKeyFormatting(self, s: str, k: int) -> str:
        cleaned = s.replace('-', '').upper()
        if not cleaned:
            return ""
        n = len(cleaned)
        rem = n % k
        parts = []
        idx = 0
        if rem != 0:
            parts.append(cleaned[:rem])
            idx = rem
        while idx < n:
            parts.append(cleaned[idx:idx+k])
            idx += k
        return "-".join(parts)
